  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('popularne', 'Strzyżenie damskie ✂️', 'Strzyżenie + mycie + modelowanie/stylizacja.', null, '-15%', array['/cennik/strzyzenie/1.webp', '/cennik/strzyzenie/2.webp', '/cennik/strzyzenie/3.webp']::text[], '[{"label":"Strzyżenie samej grzywki BEZ MYCIA","old":"40,00 zł","price":"34,00 zł","time":"15 min"},{"label":"Włosy do ramion","old":"100,00 zł","price":"85,00 zł","time":"40 min"},{"label":"Włosy do łopatek i dłuższe","old":"120,00 zł","price":"102,00 zł","time":"1 h"}]'::jsonb, 0);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('popularne', 'Nie wiem jaki zabieg', 'Konsultacja + czas na zabieg.', null, null, array['/cennik/niewiemjaki/1.webp', '/cennik/niewiemjaki/2.webp', '/cennik/niewiemjaki/3.webp']::text[], '[{"price":"Cena zmienna","time":"3 h"}]'::jsonb, 1);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('popularne', 'Odrost bez rozjaśniania', 'Usługa zawiera koloryzację odrostu do 3 cm na ciemny kolor.', null, '-15%', array['/cennik/odrostbezrozjasniania/1.webp', '/cennik/odrostbezrozjasniania/2.webp', '/cennik/odrostbezrozjasniania/3.webp']::text[], '[{"label":"Pierwsza wizyta","old":"350,00 zł","price":"297,50 zł","time":"2 h"},{"label":"Stały klient","old":"250,00 zł","price":"212,50 zł","time":"2 h"}]'::jsonb, 2);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Nie wiem jaki kolor', 'Konsultacja + czas przeznaczony na wizytę. Jeżeli nie wiesz, jaką koloryzację wybrać, ta usługa jest dla Ciebie :)', null, null, array['/cennik/niewiemjakikolor/1.webp', '/cennik/niewiemjakikolor/2.webp', '/cennik/niewiemjakikolor/3.webp', '/cennik/niewiemjakikolor/4.webp']::text[], '[{"price":"Cena zmienna","time":"3 h"}]'::jsonb, 0);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Tonowanie', 'Jeżeli Twój blond nie jest już chłodnym blondem, brąz przechodzi w rudości, a jeszcze nie chcesz ponawiać koloryzacji permanentnej – ta usługa jest dla Ciebie! Usługa obejmuje tonowanie całej długości włosa, mycie i modelowanie.', null, '-15%', array['/cennik/tonowanie/1.webp', '/cennik/tonowanie/2.webp']::text[], '[{"label":"Włosy do ramion","old":"150,00 zł","price":"127,50 zł","time":"1 h 30 min"},{"label":"Włosy do łopatek","old":"250,00 zł","price":"212,50 zł","time":"1 h 30 min"},{"label":"Włosy do talii","old":"350,00 zł","price":"297,50 zł","time":"1 h 30 min"}]'::jsonb, 1);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Odrost bez rozjaśniania', 'Usługa zawiera koloryzację odrostu do 3 cm na ciemny kolor.', null, '-15%', array['/cennik/odrostbezrozjasniania/1.webp', '/cennik/odrostbezrozjasniania/2.webp', '/cennik/odrostbezrozjasniania/3.webp']::text[], '[{"label":"Pierwsza wizyta","old":"350,00 zł","price":"297,50 zł","time":"2 h"},{"label":"Stały klient","old":"250,00 zł","price":"212,50 zł","time":"2 h"}]'::jsonb, 2);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Front blond | delikatne pojaśnienia', 'Nowoczesne rozjaśnienie frontów włosów do maksymalnej ilości 10 folii. Istnieje również możliwość rozłożenia pojaśnień, tak aby uzyskać delikatne rozjaśnienie całej fryzury. Cena jest taka sama dla każdej długości włosa.', null, '-15%', array['/cennik/frontblond/1.webp', '/cennik/frontblond/2.webp', '/cennik/frontblond/3.webp']::text[], '[{"old":"400,00 zł","price":"340,00 zł","time":"2 h"}]'::jsonb, 3);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Balejaż niteczkowy | pasemka | refleks + tonowanie', 'Wybierz tę usługę, jeżeli pragniesz rozjaśnić swoje włosy metodą całościową, pasemkami lub refleksami. W usługę wlicza się balejaż niteczkowy / refleksy / pojaśnienia min. 50% oraz odrost, tonowanie i modelowanie/loki/fale.', null, '-15%', array['/cennik/balejazniteczkowy/1.webp', '/cennik/balejazniteczkowy/2.webp', '/cennik/balejazniteczkowy/3.webp', '/cennik/balejazniteczkowy/4.webp', '/cennik/balejazniteczkowy/5.webp', '/cennik/balejazniteczkowy/6.webp']::text[], '[{"label":"Włosy do ramion","old":"550,00 zł","price":"467,50 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"650,00 zł","price":"552,50 zł","time":"3 h"},{"label":"Włosy do talii","old":"750,00 zł","price":"637,50 zł","time":"3 h"}]'::jsonb, 4);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Koloryzacja blond + tonowanie', 'Usługa polega na dekoloryzacji odrostu oraz tonowaniu reszty włosa. Jeżeli chcesz zrobić również refleksy lub pojaśnienia – wybierz usługę POJAŚNIENIA.', null, '-15%', array['/cennik/koloryzacjablond/1.webp', '/cennik/koloryzacjablond/2.webp']::text[], '[{"label":"Włosy do ramion","old":"450,00 zł","price":"382,50 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"590,00 zł","price":"501,50 zł","time":"3 h"},{"label":"Włosy długie (do talii)","old":"650,00 zł","price":"552,50 zł","time":"3 h 30 min"}]'::jsonb, 5);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Koloryzacja jednotonowa', 'Koloryzacja jednotonowa to pokrycie całych włosów farbą permanentną – jednym odcieniem farby po całej długości.', null, '-15%', array['/cennik/koloryzacjajednotonowa/1.webp']::text[], '[{"label":"Włosy do ramion","old":"290,00 zł","price":"246,50 zł","time":"2 h"},{"label":"Włosy do łopatek","old":"390,00 zł","price":"331,50 zł","time":"2 h"},{"label":"Włosy do talii","old":"490,00 zł","price":"416,50 zł","time":"2 h"}]'::jsonb, 6);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Koloryzacja wielotonowa', 'Koloryzacja wielotonowa (inaczej koloryzacja 3D) to technika, w której stosuje się co najmniej dwa kolory bazowe. Dzięki niej kolor jest głębszy, bardziej naturalny i nie jest „płaski”. W tej usłudze wliczamy również farbowanie odrostu na inny kolor niż reszta włosów po długości.', null, '-15%', array['/cennik/koloryzacjawielotonowa/1.webp', '/cennik/koloryzacjawielotonowa/2.webp']::text[], '[{"label":"Włosy do ramion","old":"350,00 zł","price":"297,50 zł","time":"2 h"},{"label":"Włosy do łopatek","old":"450,00 zł","price":"382,50 zł","time":"2 h"},{"label":"Włosy do talii","old":"550,00 zł","price":"467,50 zł","time":"2 h"}]'::jsonb, 7);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Air Touch | koloryzacje indywidualne', 'Najbardziej nowoczesne techniki koloryzacji dopasowane indywidualnie do Twojego stylu, urody oraz możliwości na włosach.', null, '-15%', array['/cennik/airtouch/1.webp', '/cennik/airtouch/2.webp', '/cennik/airtouch/3.webp', '/cennik/airtouch/4.webp']::text[], '[{"label":"Włosy do ramion","old":"750,00 zł","price":"637,50 zł","time":"4 h"},{"label":"Włosy do łopatek","old":"1 100,00 zł","price":"935,00 zł","time":"5 h"},{"label":"Włosy do talii","old":"1 400,00 zł+","price":"1 190,00 zł+","time":"6 h 30 min"}]'::jsonb, 8);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Dekoloryzacja + koloryzacja', 'Dekoloryzacja znana jest też jako ściąganie koloru z włosów. Jest to zabieg usunięcia sztucznych barwników z wnętrza włosa – pigmentów wprowadzonych tam podczas koloryzacji. Po dekoloryzacji nakładana jest pożądana koloryzacja.', null, '-15%', array['/cennik/dekoloryzacjakoloryzacja/1.webp', '/cennik/dekoloryzacjakoloryzacja/2.webp']::text[], '[{"label":"Dekoloryzacja poprzez zabieg rekonstrukcji","price":"Cena zmienna","time":"3 h 30 min"},{"label":"Włosy do łopatek","old":"850,00 zł","price":"722,50 zł","time":"4 h"},{"label":"Włosy do talii","old":"1 000,00 zł","price":"850,00 zł","time":"4 h 30 min"}]'::jsonb, 9);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Kąpiel rozjaśniająca | oczyszczenie koloru 1 ton', 'Poszukujesz sposobu na delikatne rozjaśnienie włosów? Nie chcesz narażać ich na silne, inwazyjne zabiegi takie jak dekoloryzacja, ale zależy Ci na uzyskaniu choć trochę jaśniejszego koloru? Jeśli tak, pomoże Ci kąpiel rozjaśniająca.', null, '-15%', '{}'::text[], '[{"label":"Włosy do ramion","old":"150,00 zł","price":"127,50 zł","time":"1 h"},{"label":"Włosy za ramiona","old":"200,00 zł","price":"170,00 zł","time":"1 h"}]'::jsonb, 10);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('koloryzacja', 'Repigmentacja – dodatek do usługi', 'Repigmentacja to zabieg chemiczny, który polega na przywróceniu pigmentów utraconych podczas rozjaśniania i farbowania włosów. Może być stosowana także w przypadku bardzo jasnych włosów.', null, '-15%', '{}'::text[], '[{"old":"150,00 zł","price":"127,50 zł","time":"45 min"}]'::jsonb, 11);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('pielegnacja', 'Ampułka regeneracyjna ❄️', 'Złota ampułka to ekspresowa kuracja do włosów suchych, matowych i zniszczonych, idealna także po zabiegach chemicznych.', null, '-15%', array['/cennik/ampulkaregeneracyjna/1.webp', '/cennik/ampulkaregeneracyjna/2.webp', '/cennik/ampulkaregeneracyjna/3.webp']::text[], '[{"old":"150,00 zł","price":"127,50 zł","time":"1 h"}]'::jsonb, 0);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('pielegnacja', 'Rekonstrukcja Joico ❄️', 'JOICO K-Pak – najlepsza dostępna rekonstrukcja na zimno na rynku – to silnie regenerująca kuracja przeznaczona do włosów zniszczonych, osłabionych i łamliwych. Wzmacnia pasma, poprawia ich kondycję i pomaga przywrócić elastyczność oraz połysk – efekty są widoczne już po pierwszym użyciu.', null, '-15%', array['/cennik/rekonstrukcjajoico/1.webp', '/cennik/rekonstrukcjajoico/2.webp']::text[], '[{"old":"150,00 zł","price":"127,50 zł","time":"1 h"}]'::jsonb, 1);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('pielegnacja', 'Maska na ciepło 🔥', 'Profesjonalna, odbudowująca maska do włosów, również po zabiegach chemicznych. Dzięki aminokwasom, białkom, fibroinie i nanokapsułkom intensywnie regeneruje włókna włosów, zapobiega łamliwości i chroni kolor. Idealna po koloryzacji, dekoloryzacji czy innych zabiegach chemicznych.', null, '-15%', array['/cennik/maskanacieplo/1.webp']::text[], '[{"old":"150,00 zł","price":"127,50 zł","time":"1 h"}]'::jsonb, 2);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Nie wiem jaki zabieg', 'Konsultacja + czas na zabieg.', null, null, array['/cennik/niewiemjaki/1.webp', '/cennik/niewiemjaki/2.webp', '/cennik/niewiemjaki/3.webp']::text[], '[{"price":"Cena zmienna","time":"3 h"}]'::jsonb, 0);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Rekonstrukcja włosów | trudne przypadki | hybrydy', 'Konsultacja + czas na wykonanie zabiegu trwałej rekonstrukcji włosa.', null, null, array['/cennik/rekonstrukcjatrudneprzypadki/1.webp', '/cennik/rekonstrukcjatrudneprzypadki/2.webp', '/cennik/rekonstrukcjatrudneprzypadki/3.webp', '/cennik/rekonstrukcjatrudneprzypadki/4.webp', '/cennik/rekonstrukcjatrudneprzypadki/5.webp', '/cennik/rekonstrukcjatrudneprzypadki/6.webp']::text[], '[{"price":"Cena zmienna","time":"3 h"}]'::jsonb, 1);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Kauteryzacja włosa', 'Zabieg to ratunek dla najbardziej uwrażliwionych włosów, również tych po procesie rozjaśniania, nieprzechodzących testu włosa.', null, '-15%', array['/cennik/kauteryzacjawlosa/1.webp', '/cennik/kauteryzacjawlosa/2.webp']::text[], '[{"label":"Włosy do ramion","old":"200,00 zł","price":"170,00 zł","time":"2 h"},{"label":"Włosy do łopatek","old":"250,00 zł","price":"212,50 zł","time":"2 h 30 min"},{"label":"Włosy do talii","old":"300,00 zł","price":"255,00 zł","time":"2 h 30 min"},{"label":"Włosy dłuższe","old":"350,00 zł","price":"297,50 zł","time":"3 h"}]'::jsonb, 2);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Botoks organiczny', 'Btox Organic to zaawansowany, brazylijski zabieg kapilarny (botoks na włosy) stworzony z myślą o głębokiej regeneracji, redukcji objętości oraz eliminacji puszenia się pasm.', null, '-15%', array['/cennik/botoksorganiczny/1.webp', '/cennik/botoksorganiczny/2.webp']::text[], '[{"label":"Włosy do ramion","old":"450,00 zł","price":"382,50 zł","time":"2 h 30 min"},{"label":"Włosy do łopatek","old":"550,00 zł","price":"467,50 zł","time":"3 h"},{"label":"Włosy do talii","old":"650,00 zł","price":"552,50 zł","time":"3 h 20 min"}]'::jsonb, 3);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Nanobotoks – do 5 miesięcy', null, 'HIT naszych klientek 🤩', '-15%', array['/cennik/nanobotoks/1.webp', '/cennik/nanobotoks/2.webp', '/cennik/nanobotoks/3.webp', '/cennik/nanobotoks/4.webp']::text[], '[{"label":"Włosy do ramion","old":"500,00 zł","price":"425,00 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"600,00 zł","price":"510,00 zł","time":"3 h 30 min"},{"label":"Włosy do talii","old":"750,00 zł","price":"637,50 zł","time":"3 h 30 min"},{"label":"Włosy dłuższe","old":"850,00 zł","price":"722,50 zł","time":"4 h"}]'::jsonb, 4);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Bioplastia – do 6 miesięcy', 'Kuracja przeciw puszeniu się włosa – dla włosów uwrażliwionych, niesfornych, plączących się czy cienkich, a także wysokoporowatych. Uszczelnia łuskę włosa, chroni przed uszkodzeniami mechanicznymi i optycznie pogrubia. To trwałe pożegnanie z puszeniem i elektryzowaniem – włosy nie reagują na zmianę pogody, a przy odpowiednio dobranych parametrach zachowują naturalną objętość. Zalecana również dla włosów falowanych, nie zmienia koloru.', null, '-15%', array['/cennik/bioplastia/1.webp', '/cennik/bioplastia/2.webp']::text[], '[{"label":"Włosy do ramion","old":"590,00 zł","price":"501,50 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"690,00 zł","price":"586,50 zł","time":"3 h 30 min"},{"label":"Włosy do talii","old":"850,00 zł","price":"722,50 zł","time":"3 h 30 min"},{"label":"Włosy dłuższe","old":"950,00 zł","price":"807,50 zł","time":"4 h"}]'::jsonb, 5);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Nanoplastia Basic | dla blondynek do 6 miesięcy', 'Najmocniejszy zabieg ze specjalnie opatentowaną formułą, wzbogaconą o 19 aminokwasów aktywnych. Trwale rozprostowuje włosy, NAWET kręcone, jednocześnie uszczelniając i odbudowując łodygę włosa.', null, '-15%', array['/cennik/nanoplastia/1.webp', '/cennik/nanoplastia/2.webp', '/cennik/nanoplastia/3.webp']::text[], '[{"label":"Włosy do ramion","old":"600,00 zł","price":"510,00 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"750,00 zł","price":"637,50 zł","time":"3 h 30 min"},{"label":"Włosy do talii","old":"950,00 zł","price":"807,50 zł","time":"4 h"},{"label":"Włosy dłuższe","old":"1 100,00 zł","price":"935,00 zł","time":"4 h 30 min"}]'::jsonb, 6);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('rekonstrukcja', 'Taninoplastia (vegan)', 'Taniny – sekret zabiegu taninoplastii.', null, '-15%', array['/cennik/taninoplastiavegan/1.webp', '/cennik/taninoplastiavegan/2.webp']::text[], '[{"label":"Włosy do ramion","old":"600,00 zł","price":"510,00 zł","time":"3 h"},{"label":"Włosy do łopatek","old":"750,00 zł","price":"637,50 zł","time":"3 h 20 min"},{"label":"Włosy do talii i dłuższe","old":"950,00 zł","price":"807,50 zł","time":"3 h 40 min"}]'::jsonb, 7);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('strzyzenie', 'Mycie + podcięcie końcówek + modelowanie', 'Usługa polega na umyciu włosów i podcięciu ich na prosto (same końcówki).', null, '-15%', '{}'::text[], '[{"label":"Włosy do ramion","old":"99,00 zł","price":"84,15 zł","time":"40 min"},{"label":"Włosy do łopatek i dłuższe","old":"110,00 zł","price":"93,50 zł","time":"1 h"}]'::jsonb, 0);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('strzyzenie', 'Mycie + stylizacja lub modelowanie', 'Mycie włosów, maska nawilżająca i suszenie z modelowaniem, prostowaniem lub stylizacja.', null, '-15%', '{}'::text[], '[{"label":"Włosy do ramion","old":"80,00 zł","price":"68,00 zł","time":"45 min"},{"label":"Włosy do łopatek i dłuższe","old":"100,00 zł","price":"85,00 zł","time":"50 min"}]'::jsonb, 1);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('strzyzenie', 'Strzyżenie damskie ✂️', 'Strzyżenie + mycie + modelowanie/stylizacja.', null, '-15%', array['/cennik/strzyzenie/1.webp', '/cennik/strzyzenie/2.webp', '/cennik/strzyzenie/3.webp']::text[], '[{"label":"Strzyżenie samej grzywki BEZ MYCIA","old":"40,00 zł","price":"34,00 zł","time":"15 min"},{"label":"Włosy do ramion","old":"100,00 zł","price":"85,00 zł","time":"40 min"},{"label":"Włosy do łopatek i dłuższe","old":"120,00 zł","price":"102,00 zł","time":"1 h"}]'::jsonb, 2);
  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('czesanie', '🚀 Makijaż + fryzura 2w1', 'Usługa 2w1, która pozwoli zaoszczędzić Ci czas w ważnym dla Ciebie dniu.', null, null, array['/cennik/makijazfryzura/1.webp', '/cennik/makijazfryzura/2.webp', '/cennik/makijazfryzura/3.webp', '/cennik/makijazfryzura/4.webp', '/cennik/makijazfryzura/5.webp', '/cennik/makijazfryzura/6.webp', '/cennik/makijazfryzura/7.webp', '/cennik/makijazfryzura/8.webp', '/cennik/makijazfryzura/9.webp', '/cennik/makijazfryzura/10.webp', '/cennik/makijazfryzura/11.webp', '/cennik/makijazfryzura/12.webp', '/cennik/makijazfryzura/13.webp', '/cennik/makijazfryzura/14.webp', '/cennik/makijazfryzura/15.webp']::text[], '[{"price":"550,00 zł","time":"1 h 30 min"}]'::jsonb, 0);
