  insert into public.price_services (category_id, name, description, badge, discount, images, variants, sort) values ('czesanie', '💄 Makijaż okolicznościowy | makijaż ślubny', 'Profesjonalny makijaż dopasowany do indywidualnych potrzeb i typu urody – dzienny, wieczorowy oraz na specjalne okazje, takie jak śluby i sesje zdjęciowe. Używamy wyłącznie wysokiej jakości kosmetyków. Na wizytę zapraszamy bez makijażu, a dzień wcześniej warto zadbać o nawilżenie skóry.', null, '-10%', array['/cennik/makijazokolicznosciowy/1.webp', '/cennik/makijazokolicznosciowy/2.webp', '/cennik/makijazokolicznosciowy/3.webp', '/cennik/makijazokolicznosciowy/4.webp', '/cennik/makijazokolicznosciowy/5.webp', '/cennik/makijazokolicznosciowy/6.webp', '/cennik/makijazokolicznosciowy/7.webp', '/cennik/makijazokolicznosciowy/8.webp', '/cennik/makijazokolicznosciowy/9.webp', '/cennik/makijazokolicznosciowy/10.webp', '/cennik/makijazokolicznosciowy/11.webp', '/cennik/makijazokolicznosciowy/12.webp']::text[], '[{"label":"Makijaż dzienny / biznesowy (delikatny, bez rzęs)","old":"230,00 zł","price":"207,00 zł","time":"1 h"},{"label":"Makijaż okolicznościowy","old":"280,00 zł","price":"252,00 zł","time":"1 h 30 min"},{"label":"Makijaż ślubny / próba","old":"300,00 zł","price":"270,00 zł","time":"1 h 30 min"}]'::jsonb, 3);
